CREATE POLICY "Users update own profile" ON public.profiles FOR UPDATE TO authenticated USING (user_id = auth.uid());

CREATE POLICY "Users read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY "No self role insert" ON public.user_roles FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY "No self role update" ON public.user_roles FOR UPDATE TO authenticated USING (false);
CREATE POLICY "Admin delete roles" ON public.user_roles FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Anyone reads plans" ON public.plans FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admin insert plans" ON public.plans FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin update plans" ON public.plans FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin delete plans" ON public.plans FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Anyone reads credit packs" ON public.credit_packs FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admin insert credit packs" ON public.credit_packs FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin update credit packs" ON public.credit_packs FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin delete credit packs" ON public.credit_packs FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Anyone reads config" ON public.platform_config FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admin update config" ON public.platform_config FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Users read own jobs" ON public.jobs FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Users insert own jobs" ON public.jobs FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY "Users update own jobs" ON public.jobs FOR UPDATE TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Users delete own jobs" ON public.jobs FOR DELETE TO authenticated USING (user_id = auth.uid());

